import{_ as a,o as t,c as r,a2 as d}from"./chunks/framework.D1JEzK2q.js";const f=JSON.parse('{"title":"HTTP API reference","description":"","frontmatter":{},"headers":[],"relativePath":"api/index.md","filePath":"api/index.md"}'),i={name:"api/index.md"};function n(s,e,c,o,l,h){return t(),r("div",null,[...e[0]||(e[0]=[d(`<h1 id="http-api-reference" tabindex="-1">HTTP API reference <a class="header-anchor" href="#http-api-reference" aria-label="Permalink to &quot;HTTP API reference {#http-api-reference}&quot;">​</a></h1><p>This reference documents the gateway API, including orchestration, tasks and voice. Start with <a href="/claude-gateway/api/overview.html">endpoint and authorization tables</a>, then use the detailed request fields, response schemas, errors and examples for each family below.</p><h2 id="authentication-and-public-paths" tabindex="-1">Authentication and public paths <a class="header-anchor" href="#authentication-and-public-paths" aria-label="Permalink to &quot;Authentication and public paths {#authentication-and-public-paths}&quot;">​</a></h2><p>Configure API keys in <code>gateway.api.keys</code> in <code>config.json</code>. Send <code>X-Api-Key: &lt;key&gt;</code> or <code>Authorization: Bearer &lt;key&gt;</code>. The API returns <code>401</code> for a missing key and <code>403</code> for an invalid key. Agent access is checked separately; <code>agents: &quot;*&quot;</code> grants all-agent scope, <code>write: true</code> allows scoped writes, and <code>admin: true</code> allows administrative operations. See <a href="/claude-gateway/api/agents.html#setup">key configuration examples</a>.</p><p>Public and cookie/ticket-authenticated exceptions are identified in the <a href="/claude-gateway/api/overview.html">overview</a>: health checks, provider-verified webhooks, capability share URLs, the dashboard, the paired terminal and OAuth callbacks have their own access rules. Monitoring requires admin access when keys are configured and fails closed on non-loopback keyless binds.</p><p>Use <code>http://127.0.0.1:10850</code> for a local gateway or your configured gateway origin. API routers are mounted under <code>/api</code>, so router-local <code>/v1/...</code> paths (including route-manifest entries) become public <code>/api/v1/...</code> URLs. Root paths such as <code>/health</code>, <code>/dashboard</code>, <code>/webhooks/...</code>, <code>/shared/...</code> and <code>/oauth/mcp/callback</code> do not take this prefix. No real credentials are included in these examples: replace example values with your own configured keys and identifiers.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:10850/api/v1/agents</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-Api-Key: </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$CLAUDE_GATEWAY_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><h2 id="endpoint-families" tabindex="-1">Endpoint families <a class="header-anchor" href="#endpoint-families" aria-label="Permalink to &quot;Endpoint families {#endpoint-families}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Family</th><th>Reference</th></tr></thead><tbody><tr><td>Endpoint overview</td><td><a href="/claude-gateway/api/overview.html">Open reference</a></td></tr><tr><td>System, health and route metadata</td><td><a href="/claude-gateway/api/system.html">Open reference</a></td></tr><tr><td>Agents, avatars and creation wizard</td><td><a href="/claude-gateway/api/agents.html">Open reference</a></td></tr><tr><td>Messages and slash commands</td><td><a href="/claude-gateway/api/messages.html">Open reference</a></td></tr><tr><td>SSE, tool events and reconnects</td><td><a href="/claude-gateway/api/streaming.html">Open reference</a></td></tr><tr><td>Models</td><td><a href="/claude-gateway/api/models.html">Open reference</a></td></tr><tr><td>Session management</td><td><a href="/claude-gateway/api/sessions.html">Open reference</a></td></tr><tr><td>Chat history and search</td><td><a href="/claude-gateway/api/history.html">Open reference</a></td></tr><tr><td>Workspace files</td><td><a href="/claude-gateway/api/workspace.html">Open reference</a></td></tr><tr><td>Skills and metrics</td><td><a href="/claude-gateway/api/skills.html">Open reference</a></td></tr><tr><td>Telegram access controls</td><td><a href="/claude-gateway/api/telegram.html">Open reference</a></td></tr><tr><td>WhatsApp and Cloud API</td><td><a href="/claude-gateway/api/whatsapp.html">Open reference</a></td></tr><tr><td>WeChat</td><td><a href="/claude-gateway/api/wechat.html">Open reference</a></td></tr><tr><td>Discord access controls</td><td><a href="/claude-gateway/api/discord.html">Open reference</a></td></tr><tr><td>LINE and Slack webhooks</td><td><a href="/claude-gateway/api/webhooks.html">Open reference</a></td></tr><tr><td>Cron jobs</td><td><a href="/claude-gateway/api/crons.html">Open reference</a></td></tr><tr><td>Media upload and delivery</td><td><a href="/claude-gateway/api/media.html">Open reference</a></td></tr><tr><td>File shares and image artifacts</td><td><a href="/claude-gateway/api/shares.html">Open reference</a></td></tr><tr><td>App Store, backups, proxy and app.yaml</td><td><a href="/claude-gateway/api/apps.html">Open reference</a></td></tr><tr><td>Connectors and OAuth</td><td><a href="/claude-gateway/api/connectors.html">Open reference</a></td></tr><tr><td>Package updates</td><td><a href="/claude-gateway/api/packages.html">Open reference</a></td></tr><tr><td>Paired terminal viewer</td><td><a href="/claude-gateway/api/terminal.html">Open reference</a></td></tr><tr><td>PTY screen and WebSocket</td><td><a href="/claude-gateway/api/pty.html">Open reference</a></td></tr><tr><td>Orchestration and activity</td><td><a href="/claude-gateway/api/orchestration.html">Open reference</a></td></tr><tr><td>Tasks and worker lifecycle</td><td><a href="/claude-gateway/api/tasks.html">Open reference</a></td></tr><tr><td>Voice settings and streaming</td><td><a href="/claude-gateway/api/voice.html">Open reference</a></td></tr></tbody></table><p>For command-line usage, see <a href="/claude-gateway/reference/cli-api.html">CLI and HTTP API</a>.</p>`,10)])])}const u=a(i,[["render",n]]);export{f as __pageData,u as default};
